/** Texts with numbers or names in them: matched in order, the first one that fits wins. */
internal val PT_PATTERNS: List<Pair<Regex, (MatchResult) -> String>> = listOf(
    Regex("(\\d+) of (\\d+) done") to { m: MatchResult -> "${m.groupValues[1]} de ${m.groupValues[2]} concluídos" },
    Regex("(\\d+)/(\\d+) today") to { m: MatchResult -> "${m.groupValues[1]}/${m.groupValues[2]} hoje" },
    Regex("(\\d+) days") to { m: MatchResult -> "${m.groupValues[1]} dias" },
    Regex("(\\d+) minutes?") to { m: MatchResult -> "${m.groupValues[1]} minutos" },
    Regex("(\\d+) days ago") to { m: MatchResult -> "há ${m.groupValues[1]} dias" },
    Regex("(\\d+)d ago") to { m: MatchResult -> "há ${m.groupValues[1]}d" },
    Regex("(\\d+)d left") to { m: MatchResult -> "faltam ${m.groupValues[1]}d" },
    Regex("in (\\d+) days") to { m: MatchResult -> "em ${m.groupValues[1]} dias" },
    Regex("in (\\d+)d") to { m: MatchResult -> "em ${m.groupValues[1]}d" },
    Regex("in (\\d+) h (\\d+) min") to { m: MatchResult -> "em ${m.groupValues[1]} h ${m.groupValues[2]} min" },
    Regex("in (\\d+) h") to { m: MatchResult -> "em ${m.groupValues[1]} h" },
    Regex("in (\\d+) min") to { m: MatchResult -> "em ${m.groupValues[1]} min" },
    Regex("in (\\d+)([hm])") to { m: MatchResult -> "em ${m.groupValues[1]}${m.groupValues[2]}" },
    Regex("(\\d+) TO GO") to { m: MatchResult -> "FALTAM ${m.groupValues[1]}" },
    Regex("NEXT (\\d+) DAYS") to { m: MatchResult -> "PRÓXIMOS ${m.groupValues[1]} DIAS" },
    Regex("Nothing in the next (\\d+) days\\.?") to { m: MatchResult -> "Nada nos próximos ${m.groupValues[1]} dias" + if (m.value.endsWith(".")) "." else "" },
    Regex("from (\\d+:\\d+)") to { m: MatchResult -> "a partir das ${m.groupValues[1]}" },
    Regex("Today · (.*)") to { m: MatchResult -> "Hoje · ${m.groupValues[1]}" },
    Regex("Tomorrow · (.*)") to { m: MatchResult -> "Amanhã · ${m.groupValues[1]}" },
    Regex("(.*) · best (\\d+)") to { m: MatchResult -> "${m.groupValues[1]} · melhor ${m.groupValues[2]}" },
    Regex("1 (day|week)") to { m: MatchResult -> if (m.groupValues[1] == "day") "1 dia" else "1 semana" },
    Regex("(\\d+) (day|week)s") to { m: MatchResult -> "${m.groupValues[1]} " + if (m.groupValues[2] == "day") "dias" else "semanas" },
    Regex("(day|week)s? streak") to { m: MatchResult -> "sequência de " + if (m.groupValues[1] == "day") "dias" else "semanas" },
    Regex("Every (\\d+) days") to { m: MatchResult -> "A cada ${m.groupValues[1]} dias" },
    Regex("every (\\d+) min") to { m: MatchResult -> "a cada ${m.groupValues[1]} min" },
    Regex("Delete note\\?") to { _: MatchResult -> "Eliminar nota?" },
    Regex("Delete (\\d+) notes\\?") to { m: MatchResult -> "Eliminar ${m.groupValues[1]} notas?" },
    Regex("Delete “(.*)”\\?") to { m: MatchResult -> "Eliminar “${m.groupValues[1]}”?" },
    Regex("Link to new note “(.*)”") to { m: MatchResult -> "Ligar à nova nota “${m.groupValues[1]}”" },
    Regex("Recording\\s+(\\d+:\\d\\d)") to { m: MatchResult -> "A gravar  ${m.groupValues[1]}" },
    Regex("\\+(\\d+) more · tap to open") to { m: MatchResult -> "+${m.groupValues[1]} mais · toque para abrir" },
    Regex("Reminding you every (\\d+) min until you tap Done") to { m: MatchResult -> "Vou lembrá-lo a cada ${m.groupValues[1]} min até tocar em Concluído" },
    Regex("At the start \\+ (\\d+) min before") to { m: MatchResult -> "No início + ${m.groupValues[1]} min antes" },
    Regex("At the start \\+ (\\d+) h before") to { m: MatchResult -> "No início + ${m.groupValues[1]} h antes" },
    Regex("At the start \\+ (\\d+) days? before") to { m: MatchResult -> "No início + ${m.groupValues[1]} " + (if (m.groupValues[1] == "1") "dia" else "dias") + " antes" },
    Regex("Deleted notes are kept for (.*), then removed for good\\. Change this in Settings\\.") to
        { m: MatchResult -> "As notas eliminadas são mantidas durante ${Lang.tr(m.groupValues[1])} e depois removidas definitivamente. Altere em Definições." },
    Regex("All (\\d+) recently deleted notes will be removed and can't be brought back\\.") to
        { m: MatchResult -> "As ${m.groupValues[1]} notas eliminadas recentemente serão removidas e não podem ser recuperadas." },
    Regex("It's removed from (.*)\\.") to { m: MatchResult -> "É removido de ${Lang.tr(m.groupValues[1])}." },
    Regex("This deletes every repeat of the event from (.*)\\.") to { m: MatchResult -> "Isto elimina todas as repetições do evento de ${Lang.tr(m.groupValues[1])}." },
)
